cd /home/claude/periodic3d && python3 << 'EOF'
import json
data = json.load(open('elements.json'))
js_array = json.dumps(data)

template = '''import React, { useState, useMemo, useCallback } from 'react';
import Plot from 'react-plotly.js';

const ELEMENTS = ''' + js_array + ''';

const BLOCK_INFO = {
  s: { color: '#52E3C2', label: 's — single shell occupant', max: 2 },
  p: { color: '#F6A150', label: 'p — outward-facing', max: 6 },
  d: { color: '#B18CF2', label: 'd — inner transition', max: 10 },
  f: { color: '#F178A6', label: 'f — deep core', max: 14 },
};

const SUP = { 1:'\\u00b9',2:'\\u00b2',3:'\\u00b3',4:'\\u2074',5:'\\u2075',6:'\\u2076',7:'\\u2077',8:'\\u2078',9:'\\u2079',10:'\\u00b9\\u2070',11:'\\u00b9\\u00b9',12:'\\u00b9\\u00b2',13:'\\u00b9\\u00b3',14:'\\u00b9\\u2074' };
const BLOCK_LETTER = { s:'s', p:'p', d:'d', f:'f' };

function notation(e) {
  return `${e.n}${BLOCK_LETTER[e.block]}${SUP[e.count] || e.count}`;
}

export default function PeriodicTable3D() {
  const [active, setActive] = useState(null);
  const [showLayers, setShowLayers] = useState(true);

  const traces = useMemo(() => {
    const t = [];

    if (showLayers) {
      Object.entries(BLOCK_INFO).forEach(([block, info], idx) => {
        const l = idx;
        t.push({
          type: 'mesh3d',
          x: [0.4, 7.6, 7.6, 0.4],
          y: [l, l, l, l],
          z: [0.4, 0.4, info.max + 0.6, info.max + 0.6],
          i: [0, 0],
          j: [1, 2],
          k: [2, 3],
          opacity: 0.10,
          color: info.color,
          hoverinfo: 'skip',
          showscale: false,
          flatshading: true,
          lighting: { ambient: 1, diffuse: 0, specular: 0 },
          name: '',
          showlegend: false,
        });
      });
    }

    Object.entries(BLOCK_INFO).forEach(([block, info]) => {
      const els = ELEMENTS.filter(e => e.block === block);
      t.push({
        type: 'scatter3d',
        mode: 'markers',
        name: `${block}-block`,
        x: els.map(e => e.n),
        y: els.map(e => SUBSHELL_INDEX[block]),
        z: els.map(e => e.count),
        customdata: els.map(e => e.z),
        marker: {
          size: 5,
          color: info.color,
          line: { color: '#060A12', width: 0.5 },
          opacity: 0.95,
        },
        hovertemplate:
          '<b>%{text}</b><extra></extra>',
        text: els.map(e => `${e.symbol} \\u2014 ${e.name}  (Z=${e.z})<br>n=${e.n}, ${block}-subshell, ${notation(e)}`),
      });
    });

    return t;
  }, [showLayers]);

  const handleHover = useCallback((evt) => {
    const pt = evt.points && evt.points[0];
    if (!pt || pt.data.type !== 'scatter3d') return;
    const z = pt.customdata;
    const el = ELEMENTS.find(e => e.z === z);
    if (el) setActive(el);
  }, []);

  return (
    <div style={{
      width: '100%',
      height: '100vh',
      background: '#070B14',
      color: '#E7ECF3',
      fontFamily: "'Inter', sans-serif",
      display: 'flex',
      flexDirection: 'column',
      overflow: 'hidden',
      position: 'relative',
    }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@500;600;700&family=Inter:wght@400;500&family=JetBrains+Mono:wght@400;600&display=swap');
      `}</style>

      <div style={{
        padding: '14px 18px 10px',
        borderBottom: '1px solid rgba(255,255,255,0.06)',
        flexShrink: 0,
      }}>
        <div style={{
          fontFamily: "'Space Grotesk', sans-serif",
          fontWeight: 700,
          fontSize: '17px',
          letterSpacing: '0.01em',
        }}>
          Periodic Table \\u2014 Valence Shell Model
        </div>
        <div style={{
          fontSize: '11.5px',
          color: '#8B97AC',
          marginTop: '3px',
          fontFamily: "'JetBrains Mono', monospace",
        }}>
          x: shell n &nbsp;\\u00b7&nbsp; y: subshell (s/p/d/f) &nbsp;\\u00b7&nbsp; z: valence electron count
        </div>
      </div>

      <div style={{ flex: 1, position: 'relative', minHeight: 0 }}>
        <Plot
          data={traces}
          onHover={handleHover}
          layout={{
            autosize: true,
            paper_bgcolor: '#070B14',
            plot_bgcolor: '#070B14',
            font: { color: '#C7D0DD', family: 'Inter, sans-serif', size: 10 },
            margin: { l: 0, r: 0, t: 0, b: 0 },
            showlegend: true,
            legend: {
              x: 0.01, y: 0.99,
              bgcolor: 'rgba(10,14,22,0.6)',
              bordercolor: 'rgba(255,255,255,0.08)',
              borderwidth: 1,
              font: { size: 10 },
            },
            scene: {
              xaxis: {
                title: { text: 'Shell (n)', font: { size: 11 } },
                range: [0, 8], dtick: 1,
                backgroundcolor: '#0A0F1A',
                gridcolor: 'rgba(255,255,255,0.08)',
                zerolinecolor: 'rgba(255,255,255,0.15)',
              },
              yaxis: {
                title: { text: 'Subshell', font: { size: 11 } },
                tickvals: [0,1,2,3],
                ticktext: ['s','p','d','f'],
                range: [-0.5, 3.5],
                backgroundcolor: '#0A0F1A',
                gridcolor: 'rgba(255,255,255,0.08)',
                zerolinecolor: 'rgba(255,255,255,0.15)',
              },
              zaxis: {
                title: { text: 'Valence e\\u207b count', font: { size: 11 } },
                range: [0, 15], dtick: 2,
                backgroundcolor: '#0A0F1A',
                gridcolor: 'rgba(255,255,255,0.08)',
                zerolinecolor: 'rgba(255,255,255,0.15)',
              },
              camera: {
                eye: { x: 1.6, y: -1.8, z: 1.1 },
              },
              aspectmode: 'manual',
              aspectratio: { x: 1.3, y: 0.9, z: 1.3 },
            },
          }}
          useResizeHandler
          style={{ width: '100%', height: '100%' }}
          config={{ displayModeBar: false, scrollZoom: true }}
        />
      </div>

      <div style={{
        padding: '12px 18px',
        borderTop: '1px solid rgba(255,255,255,0.06)',
        flexShrink: 0,
        minHeight: '64px',
        display: 'flex',
        alignItems: 'center',
        gap: '14px',
      }}>
        {active ? (
          <>
            <div style={{
              fontFamily: "'Space Grotesk', sans-serif",
              fontWeight: 700,
              fontSize: '22px',
              color: BLOCK_INFO[active.block].color,
              minWidth: '46px',
            }}>
              {active.symbol}
            </div>
            <div style={{ flex: 1, minWidth: 0 }}>
              <div style={{ fontSize: '13px', fontWeight: 500 }}>
                {active.name} <span style={{ color: '#8B97AC' }}>(Z={active.z})</span>
              </div>
              <div style={{
                fontSize: '11px',
                color: '#8B97AC',
                fontFamily: "'JetBrains Mono', monospace",
                marginTop: '2px',
              }}>
                n={active.n} \\u00b7 {active.block}-subshell \\u00b7 {notation(active)} \\u00b7 period {active.period}
              </div>
            </div>
          </>
        ) : (
          <div style={{ fontSize: '12px', color: '#8B97AC' }}>
            Drag to rotate \\u00b7 scroll to zoom \\u00b7 hover an element for details
          </div>
        )}
        <button
          onClick={() => setShowLayers(s => !s)}
          style={{
            background: showLayers ? 'rgba(255,255,255,0.08)' : 'transparent',
            border: '1px solid rgba(255,255,255,0.15)',
            color: '#C7D0DD',
            borderRadius: '6px',
            padding: '6px 10px',
            fontSize: '11px',
            fontFamily: "'Inter', sans-serif",
            cursor: 'pointer',
            flexShrink: 0,
          }}
        >
          {showLayers ? 'Hide layers' : 'Show layers'}
        </button>
      </div>
    </div>
  );
}
'''

with open('PeriodicTable3D.jsx','w') as f:
    f.write(template)

print("done", len(template))
EOF

