const handleHover = useCallback((evt) => {
  const pt = evt.points && evt.points[0];
  if (!pt || pt.data.type !== 'scatter3d') return;
  const z = pt.customdata;
  const el = ELEMENTS.find(e => e.z === z);
  if (el) setActive(el);
}, []);

