template = '''import React, { useEffect, useRef, useState } from 'react';
import * as THREE from 'three';

const ELEMENTS = ''' + js_array + ''';

const BLOCK_HEX = { s: 0x52e3c2, p: 0xf6a150, d: 0xb18cf2, f: 0xf178a6 };
const BLOCK_CSS = { s: '#52E3C2', p: '#F6A150', d: '#B18CF2', f: '#F178A6' };
const BLOCK_MAX = { s: 2, p: 6, d: 10, f: 14 };
const BLOCK_ORDER = ['s', 'p', 'd', 'f'];

const SUP = { 1:'\u00b9',2:'\u00b2',3:'\u00b3',4:'\u2074',5:'\u2075',6:'\u2076',7:'\u2077',8:'\u2078',9:'\u2079',10:'\u00b9\u2070',11:'\u00b9\u00b9',12:'\u00b9\u00b2',13:'\u00b9\u00b3',14:'\u00b9\u2074' };

function notation(e) {
  return `${e.n}${e.block}${SUP[e.count] || e.count}`;
}

// scaling factors for the three axes
const SX = 1.35; // shell number (n)
const SY = 2.6;  // subshell layer (l)
const SZ = 0.42; // valence electron count

function posFor(e) {
  return [
    (e.n - 4) * SX,
    (e.l - 1.5) * SY,
    (e.count - 7.5) * SZ,
  ];
}

function makeLabelSprite(text, color) {
  const canvas = document.createElement('canvas');
  const size = 128;
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d');
  ctx.font = '600 56px "Space Grotesk", sans-serif';
  ctx.fillStyle = color;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(text, size / 2, size / 2 + 4);
  const texture = new THREE.CanvasTexture(canvas);
  texture.minFilter = THREE.LinearFilter;
  const material = new THREE.SpriteMaterial({ map: texture, transparent: true, depthTest: false });
  const sprite = new THREE.Sprite(material);
  sprite.scale.set(0.9, 0.9, 1);
  return sprite;
}

export default function PeriodicTable3D() {
  const mountRef = useRef(null);
  const layerGroupRef = useRef(null);
  const [active, setActive] = useState(null);
  const [showLayers, setShowLayers] = useState(true);

  useEffect(() => {
    const mount = mountRef.current;
    let width = mount.clientWidth;
    let height = mount.clientHeight;

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x070b14);

    const camera = new THREE.PerspectiveCamera(42, width / height, 0.1, 100);
    camera.position.set(0, 0, 15);

    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    renderer.setSize(width, height);
    mount.appendChild(renderer.domElement);

    scene.add(new THREE.AmbientLight(0xffffff, 0.9));
    const dirLight = new THREE.DirectionalLight(0xffffff, 0.7);
    dirLight.position.set(6, 8, 10);
    scene.add(dirLight);

    const group = new THREE.Group();
    scene.add(group);

    const layerGroup = new THREE.Group();
    group.add(layerGroup);
    layerGroupRef.current = layerGroup;

    // translucent layer planes, one per subshell
    BLOCK_ORDER.forEach((block, idx) => {
      const max = BLOCK_MAX[block];
      const planeW = 7.6 * SX;
      const planeH = (max + 1) * SZ;
      const geo = new THREE.PlaneGeometry(planeW, planeH);
      const mat = new THREE.MeshBasicMaterial({
        color: BLOCK_HEX[block],
        transparent: true,
        opacity: 0.09,
        side: THREE.DoubleSide,
        depthWrite: false,
      });
      const mesh = new THREE.Mesh(geo, mat);
      mesh.rotation.x = -Math.PI / 2;
      const centerZ = ((1 + max) / 2 - 7.5) * SZ;
      mesh.position.set(0, (idx - 1.5) * SY, centerZ);
      layerGroup.add(mesh);

      // subshell label (s/p/d/f) on the left edge of each layer
      const label = makeLabelSprite(block, BLOCK_CSS[block]);
      label.position.set(-planeW / 2 - 0.6, (idx - 1.5) * SY, centerZ);
      layerGroup.add(label);
    });

    // shell-number (n) axis labels along the bottom
    for (let n = 1; n <= 7; n++) {
      const label = makeLabelSprite(String(n), '#8B97AC');
      label.scale.set(0.55, 0.55, 1);
      label.position.set((n - 4) * SX, (0 - 1.5) * SY - ((BLOCK_MAX['s'] + 1) * SZ) / 2 - 0.5, (0 + 1) / 2 * SZ + ((1 + BLOCK_MAX['s']) / 2 - 7.5) * SZ);
      group.add(label);
    }

    // element spheres
    const sphereGeo = new THREE.SphereGeometry(0.13, 14, 14);
    const meshes = [];
