      const mat = new THREE.MeshStandardMaterial({
        color: BLOCK_HEX[e.block],
        roughness: 0.35,
        metalness: 0.15,
      });
      const mesh = new THREE.Mesh(sphereGeo, mat);
      const [x, y, z] = posFor(e);
      mesh.position.set(x, y, z);
      mesh.userData = e;
      group.add(mesh);
      meshes.push(mesh);
    });

    group.rotation.set(-0.35, 0.6, 0);

    const raycaster = new THREE.Raycaster();
    const pointer = new THREE.Vector2();

    let isDragging = false;
    let last = { x: 0, y: 0 };
    let down = { x: 0, y: 0 };

    function setPointer(clientX, clientY) {
      const rect = renderer.domElement.getBoundingClientRect();
      pointer.x = ((clientX - rect.left) / rect.width) * 2 - 1;
      pointer.y = -((clientY - rect.top) / rect.height) * 2 + 1;
    }

    function pickElement() {
      raycaster.setFromCamera(pointer, camera);
      const intersects = raycaster.intersectObjects(meshes);
      if (intersects.length > 0) {
        setActive(intersects[0].object.userData);
      }
    }

    function onPointerDown(e) {
      isDragging = true;
      last = { x: e.clientX, y: e.clientY };
      down = { x: e.clientX, y: e.clientY };
    }
    function onPointerMove(e) {
      setPointer(e.clientX, e.clientY);
      if (isDragging) {
        const dx = e.clientX - last.x;
        const dy = e.clientY - last.y;
        group.rotation.y += dx * 0.006;
        group.rotation.x += dy * 0.006;
        group.rotation.x = Math.max(-1.4, Math.min(1.4, group.rotation.x));
        last = { x: e.clientX, y: e.clientY };
      } else {
        pickElement();
      }
    }
    function onPointerUp(e) {
      isDragging = false;
      const dx = e.clientX - down.x;
      const dy = e.clientY - down.y;
      if (Math.sqrt(dx * dx + dy * dy) < 6) {
        setPointer(e.clientX, e.clientY);
        pickElement();
      }
    }
    function onWheel(e) {
      e.preventDefault();
      camera.position.z = Math.max(6, Math.min(28, camera.position.z + e.deltaY * 0.01));
    }

    const el = renderer.domElement;
    el.style.touchAction = 'none';
    el.addEventListener('pointerdown', onPointerDown);
    el.addEventListener('pointermove', onPointerMove);
    el.addEventListener('pointerup', onPointerUp);
    el.addEventListener('pointerleave', onPointerUp);
    el.addEventListener('wheel', onWheel, { passive: false });

    function onResize() {
      width = mount.clientWidth;
      height = mount.clientHeight;
      camera.aspect = width / height;
      camera.updateProjectionMatrix();
      renderer.setSize(width, height);
    }
    window.addEventListener('resize', onResize);

    let raf;
    function animate() {
      renderer.render(scene, camera);
      raf = requestAnimationFrame(animate);
    }
    animate();

    return () => {
      cancelAnimationFrame(raf);
      el.removeEventListener('pointerdown', onPointerDown);
      el.removeEventListener('pointermove', onPointerMove);
      el.removeEventListener('pointerup', onPointerUp);
      el.removeEventListener('pointerleave', onPointerUp);
      el.removeEventListener('wheel', onWheel);
      window.removeEventListener('resize', onResize);
      mount.removeChild(renderer.domElement);
