      layerGroupRef.current.visible = showLayers;
    }
  }, [showLayers]);

  return (
    <div style={{
      width: '100%',
      height: '100vh',
      background: '#070B14',
      color: '#E7ECF3',
      fontFamily: "'Inter', sans-serif",
