          fontSize: '11.5px',
          color: '#8B97AC',
          marginTop: '3px',
          fontFamily: "'JetBrains Mono', monospace",
        }}>
          x: shell n &nbsp;\u00b7&nbsp; y: subshell (s/p/d/f) &nbsp;\u00b7&nbsp; z: valence electron count
        </div>
