      <div style={{
        padding: '12px 18px',
        borderTop: '1px solid rgba(255,255,255,0.06)',
        flexShrink: 0,
        minHeight: '64px',
        display: 'flex',
        alignItems: 'center',
        gap: '14px',
      }}>
