cd /home/claude/periodic3d && node -e "
const fs = require('fs');
const src = fs.readFileSync('PeriodicTable3D.jsx','utf8');
// quick brace/paren balance check
const pairs = {'(':')','{':'}','[':']'};
const stack = [];
for (const ch of src) {
  if ('({['.includes(ch)) stack.push(ch);
  else if (')}]'.includes(ch)) {
    const open = stack.pop();
    if (pairs[open] !== ch) { console.log('MISMATCH', open, ch); process.exit(1); }
  }
}
console.log('stack remaining:', stack.length);
" 2>&1 || echo "node not available"

