import json
data = json.load(open('elements.json'))
js_array = json.dumps(data)

template = '''import React, { useEffect, useRef, useState } from 'react';
import * as THREE from 'three';

const ELEMENTS = ''' + js_array + ''';

const BLOCK_HEX = { s: 0x52e3c2, p: 0xf6a150, d: 0xb18cf2, f: 0xf178a6, g: 0x6b7790 };
const BLOCK_CSS = { s: '#52E3C2', p: '#F6A150', d: '#B18CF2', f: '#F178A6', g: '#8A96AC' };
const LAYER_LETTERS = ['s', 'p', 'd', 'f', 'g'];
const HIGHLIGHT_HEX = 0xffd166;
const HIGHLIGHT_CSS = '#FFD166';

const SUP = { 1:'\u00b9',2:'\u00b2',3:'\u00b3',4:'\u2074',5:'\u2075',6:'\u2076',7:'\u2077',8:'\u2078',9:'\u2079',10:'\u00b9\u2070',11:'\u00b9\u00b9',12:'\u00b9\u00b2',13:'\u00b9\u00b3',14:'\u00b9\u2074',18:'\u00b9\u2078' };

function notation(e) {
  return `${e.n}${e.block}${SUP[e.count] || e.count}`;
}

// uniform voxel grid: 1 unit per quantum step on every axis
const CELL = 1.0;
const BOX = 0.82;       // solid element voxel
const GHOST_BOX = 0.55; // 5f -> 5g accessible-state voxel
const NEG_BOX = 0.4;    // empty / unrealized configuration voxel

const N_MIN = 1, N_MAX = 7;   // shell number
const L_MIN = 0, L_MAX = 4;   // subshell: s,p,d,f,g
const C_MIN = 1, C_MAX = 18;  // valence electron count (max = g capacity)

function posFor(n, l, count) {
  return [
    (n - 4) * CELL,
    (l - 2) * CELL,
    (count - 9.5) * CELL,
  ];
}

function makeLabelSprite(text, color, scale = 0.7) {
  const canvas = document.createElement('canvas');
  const size = 128;
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d');
  ctx.font = '600 56px "Space Grotesk", sans-serif';
  ctx.fillStyle = color;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(text, size / 2, size / 2 + 4);
  const texture = new THREE.CanvasTexture(canvas);
  texture.minFilter = THREE.LinearFilter;
  const material = new THREE.SpriteMaterial({ map: texture, transparent: true, depthTest: false });
  const sprite = new THREE.Sprite(material);
  sprite.scale.set(scale, scale, 1);
  return sprite;
}

export default function PeriodicTable3D() {
  const mountRef = useRef(null);
  const latticeGroupRef = useRef(null);
  const excitedGroupRef = useRef(null);
  const [active, setActive] = useState(null);
  const [showLattice, setShowLattice] = useState(true);
  const [showExcited, setShowExcited] = useState(true);

  useEffect(() => {
    const mount = mountRef.current;
    let width = mount.clientWidth;
    let height = mount.clientHeight;

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x070b14);

    const camera = new THREE.PerspectiveCamera(42, width / height, 0.1, 100);
    camera.position.set(0, 0, 28);

    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    renderer.setSize(width, height);
    mount.appendChild(renderer.domElement);

    scene.add(new THREE.AmbientLight(0xffffff, 0.95));
    const dirLight = new THREE.DirectionalLight(0xffffff, 0.65);
    dirLight.position.set(8, 10, 14);
    scene.add(dirLight);

    const group = new THREE.Group();
    scene.add(group);

    const latticeGroup = new THREE.Group();
    group.add(latticeGroup);
    latticeGroupRef.current = latticeGroup;

    const excitedGroup = new THREE.Group();
    group.add(excitedGroup);
    excitedGroupRef.current = excitedGroup;

    // --- classify every cell in the (n, l, count) lattice ---
    const occupied = new Map();
    ELEMENTS.forEach((e) => occupied.set(`${e.n}_${e.l}_${e.count}`, e));

    const ghostCells = [];
    ELEMENTS.forEach((e) => {
      if (e.block === 'f' && e.n === 5) {
        ghostCells.push({ n: 5, l: 4, count: e.count, source: e });
      }
    });
    const ghostKeys = new Set(ghostCells.map((c) => `${c.n}_${c.l}_${c.count}`));

    const negByLayer = [[], [], [], [], []];
    for (let n = N_MIN; n <= N_MAX; n++) {
      for (let l = L_MIN; l <= L_MAX; l++) {
        for (let count = C_MIN; count <= C_MAX; count++) {
          const key = `${n}_${l}_${count}`;
          if (occupied.has(key) || ghostKeys.has(key)) continue;
          negByLayer[l].push([n, count]);
        }
      }
    }

    // --- outer wireframe of the full configuration-space cube ---
    {
      const boundGeo = new THREE.BoxGeometry(
        (N_MAX - N_MIN + 1) * CELL,
        (L_MAX - L_MIN + 1) * CELL,
        (C_MAX - C_MIN + 1) * CELL
      );
      const edges = new THREE.EdgesGeometry(boundGeo);
      const lines = new THREE.LineSegments(edges, new THREE.LineBasicMaterial({
        color: 0x3a4a66, transparent: true, opacity: 0.35,
      }));
      latticeGroup.add(lines);
    }

    // --- negative space: empty / physically unrealized cells, tinted by layer, near-transparent ---
    const negGeo = new THREE.BoxGeometry(NEG_BOX, NEG_BOX, NEG_BOX);
    LAYER_LETTERS.forEach((letter, l) => {
      const cells = negByLayer[l];
      if (cells.length === 0) return;
      const mat = new THREE.MeshBasicMaterial({
        color: BLOCK_HEX[letter], transparent: true, opacity: 0.05, depthWrite: false,
      });
      const inst = new THREE.InstancedMesh(negGeo, mat, cells.length);
      const m = new THREE.Matrix4();
      cells.forEach(([n, count], i) => {
        m.makeTranslation(...posFor(n, l, count));
        inst.setMatrixAt(i, m);
      });
      inst.instanceMatrix.needsUpdate = true;
      latticeGroup.add(inst);
    });

    // --- axis labels ---
    for (let n = N_MIN; n <= N_MAX; n++) {
      const label = makeLabelSprite(String(n), '#8B97AC', 0.45);
      label.position.set((n - 4) * CELL, (L_MIN - 2) * CELL - 1, (C_MIN - 9.5) * CELL - 0.6);
      latticeGroup.add(label);
    }
    LAYER_LETTERS.forEach((letter, l) => {
      const label = makeLabelSprite(letter, BLOCK_CSS[letter], 0.7);
      label.position.set((N_MIN - 4) * CELL - 1, (l - 2) * CELL, (C_MIN - 9.5) * CELL - 0.6);
      latticeGroup.add(label);
    });
    [C_MIN, C_MAX].forEach((c) => {
      const label = makeLabelSprite(String(c), '#8B97AC', 0.45);
      label.position.set((N_MAX - 4) * CELL + 1, (L_MIN - 2) * CELL, (c - 9.5) * CELL);
      latticeGroup.add(label);
    });

    // --- solid colored voxels: the 118 known elements ---
    const elementGeo = new THREE.BoxGeometry(BOX, BOX, BOX);
    const blockMat = {
      s: new THREE.MeshStandardMaterial({ color: BLOCK_HEX.s, roughness: 0.35, metalness: 0.15 }),
      p: new THREE.MeshStandardMaterial({ color: BLOCK_HEX.p, roughness: 0.35, metalness: 0.15 }),
      d: new THREE.MeshStandardMaterial({ color: BLOCK_HEX.d, roughness: 0.35, metalness: 0.15 }),
      f: new THREE.MeshStandardMaterial({ color: BLOCK_HEX.f, roughness: 0.35, metalness: 0.15 }),
    };
    const hMat = new THREE.MeshStandardMaterial({
      color: HIGHLIGHT_HEX, roughness: 0.3, metalness: 0.2,
      emissive: new THREE.Color(HIGHLIGHT_HEX), emissiveIntensity: 0.45,
    });

    const meshes = [];
    ELEMENTS.forEach((e) => {
      const mat = e.z === 1 ? hMat : blockMat[e.block];
      const mesh = new THREE.Mesh(elementGeo, mat);
      mesh.position.set(...posFor(e.n, e.l, e.count));
      mesh.userData = e;
      group.add(mesh);
      meshes.push(mesh);
    });

    // --- highlight hydrogen's voxel + project it onto each axis ---
    const H = ELEMENTS.find((e) => e.z === 1);
    const hPos = posFor(H.n, H.l, H.count);
    {
      const edges = new THREE.EdgesGeometry(elementGeo);
      const outline = new THREE.LineSegments(edges, new THREE.LineBasicMaterial({ color: HIGHLIGHT_HEX }));
      outline.position.set(...hPos);
      outline.scale.set(1.25, 1.25, 1.25);
      group.add(outline);
    }
    const nLabelPos = [(H.n - 4) * CELL, (L_MIN - 2) * CELL - 1, (C_MIN - 9.5) * CELL - 0.6];
    const lLabelPos = [(N_MIN - 4) * CELL - 1, (H.l - 2) * CELL, (C_MIN - 9.5) * CELL - 0.6];
    const cLabelPos = [(N_MAX - 4) * CELL + 1, (H.l - 2) * CELL, (H.count - 9.5) * CELL];
    [nLabelPos, lLabelPos, cLabelPos].forEach((target) => {
      const geo = new THREE.BufferGeometry().setFromPoints([
        new THREE.Vector3(...hPos), new THREE.Vector3(...target),
      ]);
      const mat = new THREE.LineDashedMaterial({
        color: HIGHLIGHT_HEX, dashSize: 0.12, gapSize: 0.08, transparent: true, opacity: 0.7,
      });
      const line = new THREE.Line(geo, mat);
      line.computeLineDistances();
      group.add(line);
    });

    // --- excited-state overlay: 5f -> 5g accessible voxels for the actinides ---
    const ghostGeo = new THREE.BoxGeometry(GHOST_BOX, GHOST_BOX, GHOST_BOX);
    const ghostMat = new THREE.MeshBasicMaterial({ color: HIGHLIGHT_HEX, transparent: true, opacity: 0.6 });
    const ghostMeshes = [];
    ghostCells.forEach((c) => {
      const mesh = new THREE.Mesh(ghostGeo, ghostMat);
      mesh.position.set(...posFor(c.n, c.l, c.count));
      mesh.userData = { ...c.source, ghost: true };
      excitedGroup.add(mesh);
      ghostMeshes.push(mesh);

      const lineGeo = new THREE.BufferGeometry().setFromPoints([
        new THREE.Vector3(...posFor(c.source.n, c.source.l, c.source.count)),
        new THREE.Vector3(...posFor(c.n, c.l, c.count)),
      ]);
      const lineMat = new THREE.LineBasicMaterial({ color: HIGHLIGHT_HEX, transparent: true, opacity: 0.35 });
      excitedGroup.add(new THREE.Line(lineGeo, lineMat));
    });

    group.rotation.set(-0.35, 0.6, 0);

    const raycaster = new THREE.Raycaster();
    const pointer = new THREE.Vector2();
    const pickable = [...meshes, ...ghostMeshes];

    let isDragging = false;
    let last = { x: 0, y: 0 };
    let down = { x: 0, y: 0 };

    function setPointer(clientX, clientY) {
      const rect = renderer.domElement.getBoundingClientRect();
      pointer.x = ((clientX - rect.left) / rect.width) * 2 - 1;
      pointer.y = -((clientY - rect.top) / rect.height) * 2 + 1;
    }
    function pickElement() {
      raycaster.setFromCamera(pointer, camera);
      const intersects = raycaster.intersectObjects(pickable);
      if (intersects.length > 0) {
        setActive(intersects[0].object.userData);
      }
    }
    function onPointerDown(e) {
      isDragging = true;
      last = { x: e.clientX, y: e.clientY };
      down = { x: e.clientX, y: e.clientY };
    }
    function onPointerMove(e) {
      setPointer(e.clientX, e.clientY);
      if (isDragging) {
        const dx = e.clientX - last.x;
        const dy = e.clientY - last.y;
        group.rotation.y += dx * 0.006;
        group.rotation.x += dy * 0.006;
        group.rotation.x = Math.max(-1.4, Math.min(1.4, group.rotation.x));
        last = { x: e.clientX, y: e.clientY };
      } else {
        pickElement();
      }
    }
    function onPointerUp(e) {
      isDragging = false;
      const dx = e.clientX - down.x;
      const dy = e.clientY - down.y;
      if (Math.sqrt(dx * dx + dy * dy) < 6) {
        setPointer(e.clientX, e.clientY);
        pickElement();
      }
    }
    function onWheel(e) {
      e.preventDefault();
      camera.position.z = Math.max(12, Math.min(60, camera.position.z + e.deltaY * 0.02));
    }

    const el = renderer.domElement;
    el.style.touchAction = 'none';
    el.addEventListener('pointerdown', onPointerDown);
    el.addEventListener('pointermove', onPointerMove);
    el.addEventListener('pointerup', onPointerUp);
    el.addEventListener('pointerleave', onPointerUp);
    el.addEventListener('wheel', onWheel, { passive: false });

    function onResize() {
      width = mount.clientWidth;
      height = mount.clientHeight;
      camera.aspect = width / height;
      camera.updateProjectionMatrix();
      renderer.setSize(width, height);
    }
    window.addEventListener('resize', onResize);

    let raf;
    function animate() {
      renderer.render(scene, camera);
      raf = requestAnimationFrame(animate);
    }
    animate();

    return () => {
      cancelAnimationFrame(raf);
      el.removeEventListener('pointerdown', onPointerDown);
      el.removeEventListener('pointermove', onPointerMove);
      el.removeEventListener('pointerup', onPointerUp);
      el.removeEventListener('pointerleave', onPointerUp);
      el.removeEventListener('wheel', onWheel);
      window.removeEventListener('resize', onResize);
      mount.removeChild(renderer.domElement);
      renderer.dispose();
      elementGeo.dispose();
      ghostGeo.dispose();
      negGeo.dispose();
    };
  }, []);

  useEffect(() => {
    if (latticeGroupRef.current) latticeGroupRef.current.visible = showLattice;
  }, [showLattice]);

  useEffect(() => {
    if (excitedGroupRef.current) excitedGroupRef.current.visible = showExcited;
  }, [showExcited]);

  return (
    <div style={{
      width: '100%',
      height: '100vh',
      background: '#070B14',
      color: '#E7ECF3',
      fontFamily: "'Inter', sans-serif",
      display: 'flex',
      flexDirection: 'column',
      overflow: 'hidden',
      position: 'relative',
    }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@500;600;700&family=Inter:wght@400;500&family=JetBrains+Mono:wght@400;600&display=swap');
      `}</style>

      <div style={{
        padding: '14px 18px 10px',
        borderBottom: '1px solid rgba(255,255,255,0.06)',
        flexShrink: 0,
      }}>
        <div style={{
          fontFamily: "'Space Grotesk', sans-serif",
          fontWeight: 700,
          fontSize: '17px',
          letterSpacing: '0.01em',
        }}>
          Periodic Table \u2014 Configuration-Space Cube
        </div>
        <div style={{
          fontSize: '11px',
          color: '#8B97AC',
          marginTop: '3px',
          fontFamily: "'JetBrains Mono', monospace",
          lineHeight: 1.5,
        }}>
          x: shell n &nbsp;\u00b7&nbsp; y: subshell (s/p/d/f/g) &nbsp;\u00b7&nbsp; z: valence e\u207b count
          <br/>
          solid = a real element \u00b7 faint tint = empty / unrealized cell \u00b7 <span style={{ color: HIGHLIGHT_CSS }}>gold</span> = H (+ axis guides) and 5f\u21925g
        </div>
      </div>

      <div ref={mountRef} style={{ flex: 1, position: 'relative', minHeight: 0 }} />

      <div style={{
        padding: '12px 18px',
        borderTop: '1px solid rgba(255,255,255,0.06)',
        flexShrink: 0,
        minHeight: '64px',
        display: 'flex',
        alignItems: 'center',
        gap: '10px',
      }}>
        {active ? (
          <>
            <div style={{
              fontFamily: "'Space Grotesk', sans-serif",
              fontWeight: 700,
              fontSize: '22px',
              color: active.z === 1 ? HIGHLIGHT_CSS : (active.ghost ? HIGHLIGHT_CSS : BLOCK_CSS[active.block]),
              minWidth: '46px',
            }}>
              {active.symbol}
            </div>
            <div style={{ flex: 1, minWidth: 0 }}>
              <div style={{ fontSize: '13px', fontWeight: 500 }}>
                {active.name} <span style={{ color: '#8B97AC' }}>(Z={active.z})</span>
                {active.ghost && <span style={{ color: HIGHLIGHT_CSS }}> \u2014 5g-accessible</span>}
              </div>
              <div style={{
                fontSize: '11px',
                color: '#8B97AC',
                fontFamily: "'JetBrains Mono', monospace",
                marginTop: '2px',
              }}>
                {active.ghost
                  ? `ground state ${notation(active)} \u00b7 can reach 5g${SUP[active.count] || active.count} within n=5`
                  : `n=${active.n} \u00b7 ${active.block}-subshell \u00b7 ${notation(active)} \u00b7 period ${active.period}`}
              </div>
            </div>
          </>
        ) : (
          <div style={{ fontSize: '12px', color: '#8B97AC' }}>
            Drag to rotate \u00b7 scroll/pinch to zoom \u00b7 tap a voxel
          </div>
        )}
        <div style={{ display: 'flex', gap: '6px', flexShrink: 0 }}>
          <button
            onClick={() => setShowLattice((s) => !s)}
            style={{
              background: showLattice ? 'rgba(255,255,255,0.08)' : 'transparent',
              border: '1px solid rgba(255,255,255,0.15)',
              color: '#C7D0DD',
              borderRadius: '6px',
              padding: '6px 9px',
              fontSize: '10.5px',
              fontFamily: "'Inter', sans-serif",
              cursor: 'pointer',
            }}
          >
            Lattice
          </button>
          <button
            onClick={() => setShowExcited((s) => !s)}
            style={{
              background: showExcited ? 'rgba(255,209,102,0.12)' : 'transparent',
              border: '1px solid rgba(255,209,102,0.35)',
              color: HIGHLIGHT_CSS,
              borderRadius: '6px',
              padding: '6px 9px',
              fontSize: '10.5px',
              fontFamily: "'Inter', sans-serif",
              cursor: 'pointer',
            }}
          >
            Excited
          </button>
        </div>
      </div>
    </div>
  );
}
'''

with open('PeriodicTable3D.jsx', 'w') as f:
    f.write(template)

print("done", len(template))
