      group.add(lbl);
    }
    for (let k = 1; k <= 2; k++) {
      const p = latticePos(1, 0, k);
      const lbl = makeLabelSprite(`k=${k}`, '#B18CF2', 0.38);
      lbl.position.set(p[0], p[1], p[2] - 0.55);
      group.add(lbl);
