const {
  Document, Packer, Paragraph, TextRun, AlignmentType,
  HeadingLevel, PageNumber, NumberFormat, Header, Footer,
  Tab, TabStopType, TabStopPosition, BorderStyle,
  LevelFormat, UnderlineType
